//! Concise exact report for the default run profile.
//!
//! Every item is the concrete value generated by replaying the seed with no
//! challenges, no held trinket, no prior player history, and a complete
//! journal (see [`crate::journal`]). Values that the
//! public `SeedReport` marks constrained (deck stock, room rewards, quest
//! options) are reported here as that profile's exact result.

mod map;

use std::collections::BTreeMap;

use serde::Serialize;

use crate::items::model::{GeneratedItem, ItemProvenance, QuestRewardRole};
use crate::items::IdentityMaps;
use crate::level::{replay_default_profile_states, LevelState};
use crate::report::{AnalyzeError, QuestReport};
use crate::rooms::init_rooms::BuilderKind;
use crate::{dungeon_from_run, init_run, parse_seed, SPD_COMMIT, SPD_VERSION};

pub use map::{decode_rle, encode_rle, ExactMap};

/// Run assumptions under which every reported value is exact.
pub const DEFAULT_PROFILE_ASSUMPTIONS: &str = "fresh run: no challenges, no trinkets, \
no items acquired outside level generation, default inventory, quests not yet started, \
journal complete (no guide or alchemy pages)";

#[derive(Debug, Clone, Copy, Default)]
pub struct ExactOptions {
    /// Include compact painter-complete floor layouts.
    pub maps: bool,
}

#[derive(Debug, Clone, Serialize)]
pub struct ExactReport {
    pub seed: String,
    pub numeric: i64,
    pub version: &'static str,
    pub commit: &'static str,
    pub assumptions: &'static str,
    pub identities: ExactIdentities,
    pub floors: Vec<ExactFloor>,
}

/// Item class to unidentified appearance.
#[derive(Debug, Clone, Serialize)]
pub struct ExactIdentities {
    pub potions: BTreeMap<&'static str, String>,
    pub scrolls: BTreeMap<&'static str, String>,
    pub rings: BTreeMap<&'static str, String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct ExactFloor {
    pub depth: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub feeling: Option<&'static str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub builder: Option<&'static str>,
    /// Room classes in generation order; repeats collapse to `Name xN`.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub rooms: Vec<String>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub items: Vec<ExactItem>,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub quests: Vec<ExactQuest>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub map: Option<ExactMap>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct ExactItem {
    pub item: String,
    #[serde(skip_serializing_if = "is_one")]
    pub qty: i32,
    #[serde(skip_serializing_if = "is_zero")]
    pub lvl: i32,
    #[serde(skip_serializing_if = "std::ops::Not::not")]
    pub cursed: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub ench: Option<String>,
    /// Container or room; absent for ordinary floor loot.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub src: Option<String>,
    /// Choices offered by this item (Trinket Catalyst).
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub options: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct ExactQuest {
    pub quest: &'static str,
    pub goal: String,
    /// The player picks one reward (Imp: one per completed vault option).
    pub rewards: Vec<ExactItem>,
}

/// Analyze a seed under the default profile and return exact values only.
pub fn analyze_seed_exact(
    input: &str,
    floors: u32,
    options: ExactOptions,
) -> Result<ExactReport, AnalyzeError> {
    let info = parse_seed(input)?;
    let mut dungeon = dungeon_from_run(init_run(info.numeric));
    let identities = identities(&dungeon.identities);
    let states = replay_default_profile_states(&mut dungeon, floors, options.maps);
    Ok(ExactReport {
        seed: info.code.unwrap_or(info.formatted),
        numeric: info.numeric,
        version: SPD_VERSION,
        commit: SPD_COMMIT,
        assumptions: DEFAULT_PROFILE_ASSUMPTIONS,
        identities,
        floors: states
            .iter()
            .map(|state| exact_floor(state, options))
            .collect(),
    })
}

fn identities(maps: &IdentityMaps) -> ExactIdentities {
    let pairs = |entries: &[crate::items::identities::IdentityEntry]| {
        entries
            .iter()
            .map(|entry| (entry.item.class_name(), entry.appearance.clone()))
            .collect()
    };
    ExactIdentities {
        potions: pairs(&maps.potions),
        scrolls: pairs(&maps.scrolls),
        rings: pairs(&maps.rings),
    }
}

fn exact_floor(state: &LevelState, options: ExactOptions) -> ExactFloor {
    let mut items = Vec::new();
    let mut rewards: Vec<(&'static str, ExactItem)> = Vec::new();
    for item in state.spawned_queue_items.iter().chain(&state.placed_items) {
        match item.provenance {
            ItemProvenance::Quest(QuestRewardRole::WandmakerPersisted) => {}
            ItemProvenance::Quest(role) if let Some(owner) = quest_option(role) => {
                rewards.push((owner, exact_item(item)));
            }
            _ if is_noise(item) => {}
            _ => push_merged(&mut items, exact_item(item)),
        }
    }
    let quests = state
        .quests
        .iter()
        .map(|quest| {
            let (name, goal) = quest_summary(quest);
            ExactQuest {
                quest: name,
                goal,
                rewards: rewards
                    .iter()
                    .filter(|(owner, _)| *owner == name)
                    .map(|(_, item)| ExactItem {
                        src: None,
                        ..item.clone()
                    })
                    .collect(),
            }
        })
        .collect();
    ExactFloor {
        depth: state.depth as u32,
        feeling: (state.feeling.as_str() != "none").then(|| state.feeling.as_str()),
        builder: state.builder.map(|builder| match builder {
            BuilderKind::Loop => "loop",
            BuilderKind::FigureEight => "figure_eight",
        }),
        rooms: collapse_rooms(&state.rooms),
        items,
        quests,
        map: options
            .maps
            .then(|| {
                state.layout_map.as_ref().map(|layout| {
                    let mut layout = layout.clone();
                    if let Some(populated) = &state.map {
                        layout.flatten_grass_under_entities(populated);
                    }
                    ExactMap::from_floor_map(&layout)
                })
            })
            .flatten(),
    }
}

/// Quest whose choose-one reward pool this role belongs to.
fn quest_option(role: QuestRewardRole) -> Option<&'static str> {
    match role {
        QuestRewardRole::GhostWeapon { .. } | QuestRewardRole::GhostArmor { .. } => Some("ghost"),
        QuestRewardRole::WandmakerWand => Some("wandmaker"),
        QuestRewardRole::BlacksmithWeapon { .. }
        | QuestRewardRole::BlacksmithMissile { .. }
        | QuestRewardRole::BlacksmithArmor { .. } => Some("blacksmith"),
        QuestRewardRole::ImpVaultOption { .. } => Some("imp"),
        QuestRewardRole::WandmakerPersisted
        | QuestRewardRole::BlacksmithRoomWeapon { .. }
        | QuestRewardRole::BlacksmithRoomMissile { .. }
        | QuestRewardRole::BlacksmithRoomArmor { .. } => None,
    }
}

fn quest_summary(quest: &QuestReport) -> (&'static str, String) {
    match quest {
        QuestReport::SadGhost { variable, .. } => ("ghost", format!("{:?}", variable.target)),
        QuestReport::OldWandmaker { variable, .. } => {
            ("wandmaker", format!("{:?}", variable.objective))
        }
        QuestReport::TrollBlacksmith { variable, .. } => {
            ("blacksmith", format!("{:?}", variable.objective))
        }
        QuestReport::AmbitiousImp { variable, .. } => {
            ("imp", format!("depth {}", variable.spawn_depth))
        }
    }
}

/// Keys, dew, and lore/guide pages are level plumbing rather than loot.
fn is_noise(item: &GeneratedItem) -> bool {
    matches!(
        item.class_name.as_str(),
        "Dewdrop"
            | "IronKey"
            | "GoldenKey"
            | "CrystalKey"
            | "AlchemyPage"
            | "GuidePage"
            | "DocumentPage"
            | "TornPage"
    )
}

fn exact_item(item: &GeneratedItem) -> ExactItem {
    ExactItem {
        item: item.class_name.clone(),
        qty: item.quantity.max(1),
        lvl: item.level,
        cursed: item.cursed,
        ench: item.enchantment.clone(),
        src: item.source.as_deref().and_then(short_source),
        options: if item.class_name == "TrinketCatalyst" {
            item.candidate_classes.clone()
        } else {
            Vec::new()
        },
    }
}

fn short_source(source: &str) -> Option<String> {
    let source = source
        .strip_suffix(":forced")
        .or_else(|| source.strip_suffix(":heap"))
        .or_else(|| source.strip_suffix(":mimic"))
        .unwrap_or(source);
    match source {
        "heap" | "forced" | "items_to_spawn" => None,
        "Ghost.Quest" | "Wandmaker.Quest" | "Blacksmith.Quest" | "Imp.Quest" => None,
        other => Some(other.split(':').next().unwrap_or(other).to_string()),
    }
}

/// Identical stacks from the same source merge into one entry.
fn push_merged(items: &mut Vec<ExactItem>, item: ExactItem) {
    if let Some(existing) = items.iter_mut().find(|existing| {
        existing.item == item.item
            && existing.lvl == item.lvl
            && existing.cursed == item.cursed
            && existing.ench == item.ench
            && existing.src == item.src
            && existing.options == item.options
    }) {
        existing.qty += item.qty;
    } else {
        items.push(item);
    }
}

fn collapse_rooms(rooms: &[String]) -> Vec<String> {
    let mut counts: Vec<(&str, usize)> = Vec::new();
    for room in rooms {
        match counts.iter_mut().find(|(name, _)| *name == room) {
            Some((_, count)) => *count += 1,
            None => counts.push((room, 1)),
        }
    }
    counts
        .into_iter()
        .map(|(name, count)| match count {
            1 => name.to_string(),
            n => format!("{name} x{n}"),
        })
        .collect()
}

fn is_one(value: &i32) -> bool {
    *value == 1
}

fn is_zero(value: &i32) -> bool {
    *value == 0
}

